  const { token, id } = params;
  const { clientId, cacheMaxEntries, cacheMaxAge } = options;

  if (!token) {
    throw new Parse.Error(Parse.Error.OBJECT_NOT_FOUND, `id token is invalid for this user.`);
  }

  const { kid: keyId } = authUtils.getHeaderFromToken(token);
  const ONE_HOUR_IN_MS = 3600000;
  let claimsData;

  // Set defaults for caching parameters
  const effectiveCacheMaxAge = cacheMaxAge || ONE_HOUR_IN_MS;
  const effectiveCacheMaxEntries = cacheMaxEntries || 5;

  const appleKeyData = await getAppleKeyByKeyId(keyId, effectiveCacheMaxEntries, effectiveCacheMaxAge);
  const signingKey = appleKeyData.publicKey || appleKeyData.rsaPublicKey;

  try {
    claimsData = jwt.verify(token, signingKey, {
      algorithms: ['RS256'],
      // the audience can be checked against a string, a regular expression or a list of strings and/or regular expressions.
      audience: clientId,
    });
  } catch (exception) {
    const errorMessage = exception.message;
    throw new Parse.Error(Parse.Error.OBJECT_NOT_FOUND, `${errorMessage}`);
  }

  if (claimsData.iss !== TOKEN_ISSUER) {
    throw new Parse.Error(
      Parse.Error.OBJECT_NOT_FOUND,
      `id token not issued by correct OpenID provider - expected: ${TOKEN_ISSUER} | from: ${claimsData.iss}`
    );
  }

  if (claimsData.sub !== id) {
    throw new Parse.Error(Parse.Error.OBJECT_NOT_FOUND, `auth data is invalid for this user.`);
  }

  return claimsData;
}

