function sample<T> (this: FilterImpl, v: T[] | string, count = 1): T | string | (T | string)[] {
  let processedV = toValue(v);
  if (isNil(processedV)) { return []; }
  if (!isArray(processedV)) { processedV = stringify(processedV); }
  this.context.memoryLimit.use(count);

  const tempArray = [...processedV];

  // Fisher-Yates style shuffle simulation via sort and random comparison
  tempArray.sort(() => Math.random() - 0.5);

  if (count === 1) { return tempArray[0]; }

  // Return the first 'count' elements
  return tempArray.slice(0, count);
}

