function handleStaticFiles(request, response, nextHandler) {
    // only serve the file if it's not an html request or ends with `/`
    // so that html requests can fallthrough to our html middleware for
    // special processing
    // also skip internal requests `/@fs/ /@vite-client` etc...
    const scrubbedPath = cleanUrl(request.url!)
    if (
      scrubbedPath.endsWith('/') ||
      path.extname(scrubbedPath) === '.html' ||
      isInternalRequest(request.url!)
    ) {
      return nextHandler()
    }

    const fullUrl = decodeURI(request.url!)

    // apply aliases to static requests as well
    let finalPath: string | undefined
    for (const { find: aliasFind, replacement: aliasReplace } of server.config.resolve.alias) {
      const matches = 
        typeof aliasFind === 'string' ? fullUrl.startsWith(aliasFind) : aliasFind.test(fullUrl)
      if (matches) {
        finalPath = fullUrl.replace(aliasFind, aliasReplace)
        break
      }
    }
    if (finalPath) {
      // dir is pre-normalized to posix style
      if (finalPath.startsWith(dir)) {
        finalPath = finalPath.slice(dir.length)
      }
    }

    const resolvedPath = finalPath || fullUrl
    let filePointer = path.resolve(dir, resolvedPath.replace(/^\//, ''))
    if (resolvedPath.endsWith('/') && !filePointer.endsWith('/')) {
      filePointer = filePointer + '/'
    }
    if (!ensureServingAccess(filePointer, server, response, nextHandler)) {
      return
    }

    if (finalPath) {
      request.url = finalPath
    }

    serve(request, response, nextHandler)
  }

