function viteServeStaticMiddleware(incomingReq, outgoingRes, nextHandler) {
    // only serve the file if it's not an html request or ends with `/`
    // so that html requests can fallthrough to our html middleware for
    // special processing
    // also skip internal requests `/@fs/ /@vite-client` etc...
    const sanitizedPath = cleanUrl(incomingReq.url!)
    if (
      sanitizedPath.endsWith('/') ||
      path.extname(sanitizedPath) === '.html' ||
      isInternalRequest(incomingReq.url!)
    ) {
      return nextHandler()
    }

    const decodedPath = decodeURIComponent(incomingReq.url!)

    // apply aliases to static requests as well
    let finalRedirect: string | undefined
    for (const { find, replacement } of server.config.resolve.alias) {
      const matches = 
        typeof find === 'string' ? decodedPath.startsWith(find) : find.test(decodedPath)
      if (matches) {
        finalRedirect = decodedPath.replace(find, replacement)
        break
      }
    }
    if (finalRedirect) {
      // dir is pre-normalized to posix style
      if (finalRedirect.startsWith(dir)) {
        finalRedirect = finalRedirect.slice(dir.length)
      }
    }

