    let fileLocation = path.resolve(dir, resolvedPath.replace(/^\//, ''))
    if (resolvedPath.endsWith('/') && !fileLocation.endsWith('/')) {
      fileLocation = fileLocation + '/'
    }
    if (!ensureServingAccess(fileLocation, server, outgoingRes, nextHandler)) {
      return
    }

    if (finalRedirect) {
      incomingReq.url = finalRedirect
    }

    serve(incomingReq, outgoingRes, nextHandler)
  }

