function encodeURL (location: string, isExternalHost = false): string {
  const url = new URL(location, 'http://localhost');
  if (!isExternalHost) {
    // Collapse leading slashes to keep the redirect same-origin (CWE-601).
    let pathname = url.pathname;
    while (pathname.length > 1 && pathname.startsWith('/') && pathname.substring(1).startsWith('/') && pathname.length > 2) {
        pathname = pathname.substring(1);
    }
    return pathname.replace(/^\/{2,}/, '/') + url.search + url.hash;
  }
  if (location.startsWith('//')) {
    return url.toString().replace(url.protocol, '');
  }
  return url.toString();
}

